import math
from itertools import combinations

def gcd(a, b):
    return math.gcd(a, b)

def gcd_three(a, b, c):
    return gcd(a, gcd(b, c))

def check_good_set(a, b, c):
    # Condition 1: GCD of all three is 1
    if gcd_three(a, b, c) != 1:
        return False

    # Condition 2: For any pair, the third element divides their product.
    # The pairs are (a, b), (a, c), (b, c). The 'other' elements are c, b, a respectively.

    # 1. c | ab
    if (a * b) % c != 0:
        return False

    # 2. b | ac
    if (a * c) % b != 0:
        return False

    # 3. a | bc
    if (b * c) % a != 0:
        return False

    return True

# Search for good sets U = {a, b, c} where 1 <= a < b < c <= 10
good_products = []
elements = range(1, 11)

for U in combinations(elements, 3):
    a, b, c = U
    if check_good_set(a, b, c):
        m = a * b * c
        good_products.append(m)

# Sort the products to easily find the 20th smallest later
good_products.sort()

print("Found good products (m):")
print(good_products)
print(f"Total number of good sets found: {len(good_products)}")

